-- 1. Create table with JSONB column
CREATE TABLE event_logs (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    payload JSONB NOT NULL
);

-- 2. Create GIN index for containment queries
CREATE INDEX idx_logs_payload_gin ON event_logs USING gin (payload);

-- 3. High-performance containment search (uses GIN index!)
SELECT id, payload->>'action' AS action
FROM event_logs
WHERE payload @> '{"user": {"tier": "enterprise"}}';

CREATE TABLE events (
    id      BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    payload JSONB NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

INSERT INTO events (payload) VALUES
  ('{"action":"login","user":{"id":42,"tier":"pro"},"tags":["web","mfa"]}'),
  ('{"action":"purchase","user":{"id":42,"tier":"pro"},"total":19.99}');

-- -> returns jsonb, ->> returns text (compare to strings with ->>)
SELECT payload->>'action'        AS action,
       payload->'user'->>'tier'  AS tier,
       payload#>>'{user,id}'     AS user_id,
       (payload->'user'->>'id')::int AS user_id_int
FROM events;

-- Containment @> is GIN-indexable
SELECT * FROM events WHERE payload @> '{"user":{"tier":"pro"}}';

-- Key existence (also GIN-indexable)
SELECT * FROM events WHERE payload ? 'total';

-- Array membership
SELECT * FROM events WHERE payload->'tags' ? 'mfa';

-- Build documents
SELECT jsonb_build_object('id', 1, 'tags', jsonb_build_array('a','b'));
SELECT jsonb_object_agg(id, payload->>'action') FROM events GROUP BY 1 LIMIT 1;

-- Merge: the right-hand side wins on conflicts
UPDATE events
SET    payload = payload || '{"source":"mobile"}'::jsonb
WHERE  id = 1;

-- Set a deeply nested key, and remove one
UPDATE events SET payload = jsonb_set(payload, '{user,tier}', '"enterprise"') WHERE id = 1;
UPDATE events SET payload = payload #- '{user,tier}'                         WHERE id = 1;

-- Expand arrays into rows
SELECT id, tag FROM events, jsonb_array_elements_text(payload->'tags') AS tag;

-- Index the whole document, a path, or a specific key
CREATE INDEX events_payload_gin  ON events USING gin (payload jsonb_path_ops);  -- smaller, containment only
CREATE INDEX events_action_idx   ON events ((payload->>'action'));              -- btree on a scalar path

CREATE TABLE posts (
    id   BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    tags TEXT[] NOT NULL DEFAULT '{}'
);

INSERT INTO posts (tags) VALUES (ARRAY['sql','postgres']), ('{performance,indexing}');

SELECT tags[1]               AS first_tag,       -- 1-based
       array_length(tags, 1) AS tag_count,
       'sql' = ANY(tags)     AS has_sql,
       tags && ARRAY['indexing'] AS overlaps
FROM posts;

-- Unnest to rows for joining against a tags table
SELECT p.id, t.tag FROM posts p, unnest(p.tags) AS t(tag) WHERE t.tag = 'sql';
UPDATE posts SET tags = array_append(tags, 'deep') WHERE id = 1;

-- GIN index for array containment/overlap
CREATE INDEX posts_tags_gin ON posts USING gin (tags);
